package com.bank.cart;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

class Product {
    final String id, name; final BigDecimal price; int stock;
    Product(String id, String name, BigDecimal price, int stock) {
        this.id = id; this.name = name; this.price = price; this.stock = stock;
    }
}

class CartItem {
    final Product product; final int qty;
    CartItem(Product product, int qty) { this.product = product; this.qty = qty; }
    BigDecimal lineTotal() { return product.price.multiply(BigDecimal.valueOf(qty)); }
}

class Cart {
    final String userId; final List<CartItem> items = new ArrayList<>();
    Cart(String userId) { this.userId = userId; }
    void add(Product p, int qty) { items.add(new CartItem(p, qty)); }
    BigDecimal subtotal() { return items.stream().map(CartItem::lineTotal).reduce(BigDecimal.ZERO, BigDecimal::add); }
}

interface DiscountStrategy { BigDecimal apply(BigDecimal subtotal); }
class PercentageDiscount implements DiscountStrategy {
    private final BigDecimal percent;
    PercentageDiscount(BigDecimal percent) { this.percent = percent; }
    public BigDecimal apply(BigDecimal subtotal) {
        return subtotal.subtract(subtotal.multiply(percent).divide(new BigDecimal("100")));
    }
}

class CheckoutService {
    private static final Logger log = Logger.getLogger("CART");
    synchronized BigDecimal process(Cart cart, DiscountStrategy discount) {
        for (CartItem it : cart.items)                       // inventory check at checkout
            if (it.product.stock < it.qty) throw new IllegalStateException("Out of stock: " + it.product.name);
        BigDecimal total = discount.apply(cart.subtotal());  // apply discount
        log.info(() -> "Charging " + total + " for " + cart.userId);  // payment integration point
        for (CartItem it : cart.items) it.product.stock -= it.qty;    // deduct only after payment ok
        return total;
    }
}

public class CartDemo {
    public static void main(String[] args) {
        Product coin = new Product("P1", "Gold Coin 1g", new BigDecimal("6000"), 10);
        Cart cart = new Cart("SAV2001"); // Rajesh
        cart.add(coin, 2);
        BigDecimal total = new CheckoutService().process(cart, new PercentageDiscount(new BigDecimal("10")));
        Logger.getLogger("CART").info("Paid total=" + total + ", stock left=" + coin.stock);
    }
}
